tool_args.content:
-- Add orders.status and backfill it without holding a lock anyone will notice.
--
-- Applied by ./db.sh apply, which is psql with ON_ERROR_STOP and one implicit transaction
-- per statement. Nothing here opens an explicit transaction block: the backfill commits
-- between batches, and a procedure that commits cannot run inside one.

-- Never queue for a lock. A DDL statement that waits behind a long running read holds a
-- place in the queue that every later query on the table waits behind too, which is how
-- a metadata change with no rewrite in it takes an application down.
SET lock_timeout = '3s';
SET statement_timeout = '60s';

-- Nullable and with no default: a catalogue change, no table rewrite, ACCESS EXCLUSIVE
-- held for as long as it takes to write one catalogue row.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS status text;

-- Backfill in batches, each its own transaction. One statement over the whole table would
-- hold row locks on every row it had touched until it finished, keep one snapshot open
-- for the duration, and write the lot to the write ahead log before anything could be
-- vacuumed. Walking the primary key in ranges keeps every batch an index scan.
CREATE OR REPLACE PROCEDURE backfill_orders_status()
LANGUAGE plpgsql AS $$
DECLARE
    batch  constant bigint := 10000;
    lo     bigint := 0;
    hi     bigint;
    top    bigint;
BEGIN
    SELECT coalesce(max(id), 0) INTO top FROM orders;
    WHILE lo < top LOOP
        hi := lo + batch;
        UPDATE orders
           SET status = CASE
                            WHEN cancelled_at IS NOT NULL THEN 'cancelled'
                            WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
                            WHEN refunded_cents > 0 THEN 'partly_refunded'
                            WHEN shipped_at IS NOT NULL THEN 'shipped'
                            ELSE 'placed'
                        END
         WHERE id > lo
           AND id <= hi
           AND status IS NULL;
        COMMIT;
        lo := hi;
    END LOOP;
END;
$$;

CALL backfill_orders_status();

DROP PROCEDURE backfill_orders_status();

-- NOT NULL in three cheap steps rather than one expensive one. A bare SET NOT NULL takes
-- ACCESS EXCLUSIVE and then scans the whole table with it held. A CHECK added NOT VALID
-- takes the same lock for a catalogue write only, VALIDATE CONSTRAINT does the scan under
-- SHARE UPDATE EXCLUSIVE, which readers and writers do not block on, and SET NOT NULL is
-- then free because the planner can prove the column from the validated constraint.
ALTER TABLE orders
    ADD CONSTRAINT orders_status_present CHECK (status IS NOT NULL) NOT VALID;

ALTER TABLE orders VALIDATE CONSTRAINT orders_status_present;

ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

ALTER TABLE orders DROP CONSTRAINT orders_status_present;

-- Reverse 0002. Every step is conditional, so this runs on a database that got part way
-- through the up migration as well as on one that finished it.
SET lock_timeout = '3s';
SET statement_timeout = '60s';

DROP PROCEDURE IF EXISTS backfill_orders_status();

ALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_status_present;

-- Catalogue only. The column's storage is reclaimed by vacuum later, not here.
ALTER TABLE orders DROP COLUMN IF EXISTS status;
